fn check(b:bool){if !b{let z=0;let _=1/z;}}struct C{cur:u8,end:u8}fn counter(end:u8)->C{C{cur:0,end}}impl core::iter::Iterator for C{type Item=u8;fn next(&mut self)->Option<u8>{if self.cur<self.end{let n=self.cur;self.cur+=1u8;Some(n)}else{None}}}struct Seq(u8);impl core::iter::IntoIterator for Seq{type Item=u8;type IntoIter=C;fn into_iter(self)->C{counter(self.0)}}impl Seq{fn into_iter(self)->C{counter(1)}}fn main(){let mut n=0u8;for x in Seq(3){n+=x;}check(n==3);let c=Seq(3).into_iter();check(c.end==1);}
